import pytest
from candidate import vowels_count


class TestVowelsCountNormal:
    def test_simple_word_with_two_vowels(self):
        assert vowels_count("abcde") == 2

    def test_uppercase_with_y_at_end(self):
        assert vowels_count("ACEDY") == 3

    def test_all_vowels_lowercase(self):
        assert vowels_count("aeiou") == 5

    def test_all_vowels_uppercase(self):
        assert vowels_count("AEIOU") == 5

    def test_single_vowel_a(self):
        assert vowels_count("a") == 1

    def test_single_vowel_e(self):
        assert vowels_count("e") == 1

    def test_single_vowel_i(self):
        assert vowels_count("i") == 1

    def test_single_vowel_o(self):
        assert vowels_count("o") == 1

    def test_single_vowel_u(self):
        assert vowels_count("u") == 1

    def test_single_vowel_A_uppercase(self):
        assert vowels_count("A") == 1

    def test_no_vowels(self):
        assert vowels_count("bcdfg") == 0

    def test_rhythm_has_no_vowels(self):
        assert vowels_count("rhythm") == 0

    def test_hello(self):
        assert vowels_count("hello") == 2

    def test_world(self):
        assert vowels_count("world") == 1


class TestVowelsCountYAtEnd:
    def test_single_y(self):
        assert vowels_count("y") == 1

    def test_single_Y_uppercase(self):
        assert vowels_count("Y") == 1

    def test_y_at_end_of_word(self):
        assert vowels_count("hey") == 2

    def test_Y_at_end_of_word(self):
        assert vowels_count("hY") == 1

    def test_y_not_at_end(self):
        assert vowels_count("yellow") == 2

    def test_y_in_middle_not_counted(self):
        assert vowels_count("rhythm") == 0

    def test_multiple_y_only_last_counts(self):
        assert vowels_count("yy") == 1

    def test_yY_only_last_counts(self):
        assert vowels_count("yY") == 1

    def test_why(self):
        assert vowels_count("Why") == 1

    def test_you(self):
        assert vowels_count("you") == 2

    def test_my(self):
        assert vowels_count("my") == 1

    def test_gym(self):
        assert vowels_count("gym") == 0

    def test_yay(self):
        assert vowels_count("yay") == 2


class TestVowelsCountMixedCase:
    def test_mixed_case_vowels(self):
        assert vowels_count("AeIoU") == 5

    def test_mixed_case_with_y_end(self):
        assert vowels_count("hElLoY") == 3

    def test_consonants_mixed(self):
        assert vowels_count("BcDfG") == 0


class TestVowelsCountBoundary:
    def test_empty_string_raises_index_error(self):
        with pytest.raises(IndexError):
            vowels_count("")

    def test_single_character_consonant(self):
        assert vowels_count("b") == 0

    def test_two_characters_both_vowels(self):
        assert vowels_count("ae") == 2

    def test_two_characters_vowel_and_y(self):
        assert vowels_count("ay") == 2

    def test_long_string_vowels(self):
        assert vowels_count("a" * 100) == 100


class TestVowelsCountErrorCases:
    def test_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            vowels_count(None)

    def test_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            vowels_count(123)

    def test_list_input_raises_type_error(self):
        with pytest.raises(TypeError):
            vowels_count(["a", "e"])


class TestVowelsCountEdgeCases:
    def test_string_with_spaces(self):
        assert vowels_count("a e") == 2

    def test_string_with_digits(self):
        assert vowels_count("a1e2") == 2

    def test_string_with_punctuation(self):
        assert vowels_count("a,e") == 2

    def test_repeated_vowel_y_end(self):
        assert vowels_count("aaaay") == 5

    def test_only_consonants_and_y_end(self):
        assert vowels_count("bcdfgy") == 1

    def test_uppercase_consonants(self):
        assert vowels_count("BCDFG") == 0

    def test_unicode_characters(self):
        assert vowels_count("a\u00e9e") == 3
